    function hexToBinary(hex,invert){
      var out = "";
      for(var i=0;i<hex.length;i+=2){
        var value = parseInt(hex.slice(i,i+2),16);
        out += String.fromCharCode(invert ? (255-value) : value);
      }
      return out;
    }
    function positiveLogoBinary(){ return hexToBinary(ESSILOR_LOGO_BITMAP_HEX,false); }
    function quotationArtwork(){
      var key = JSON.stringify([
        state.product,state.coating,state.frame,state.frameComplimentary,
        state.followups.one,state.followups.two,state.complimentary
      ]);
      if(quotationArtworkCache && quotationArtworkCache.key===key) return quotationArtworkCache;

      var canvas = document.createElement("canvas");
      canvas.width = 320;
      canvas.height = 480;
      var ctx = canvas.getContext("2d",{willReadFrequently:true});
      ctx.fillStyle = "#fff";
      ctx.fillRect(0,0,320,480);
      ctx.fillStyle = "#000";
      ctx.textBaseline = "top";

      var logo = positiveLogoBinary();
      for(var ly=0;ly<64;ly++) for(var lx=0;lx<96;lx++){
        if(logo.charCodeAt(ly*12+Math.floor(lx/8)) & (128>>(lx%8)))
          ctx.fillRect(20+lx,12+ly,1,1);
      }
      function fitText(value,x,y,maxWidth,size,minSize,weight){
        do{
          ctx.font = (weight||"bold") + " " + size + "px Arial, sans-serif";
          if(ctx.measureText(value).width<=maxWidth || size<=minSize) break;
          size--;
        }while(true);
        ctx.textAlign="left";
        ctx.fillText(value,x,y);
      }
      var p = currentProduct();
      fitText(p.name,20,101,280,36,30,"bold");
      fitText(p.tech+" · AIRWEAR 1.59",20,148,280,18,15,"bold");
      ctx.fillRect(20,186,280,2);

      var rows = [{label:coatingName(),amount:coatingPrice(),struck:false}];
      if(frameIncluded()) rows.push({label:"Frame",amount:state.frame,struck:state.frameComplimentary});
      if(state.followups.one) rows.push({label:"Follow-up 1",amount:120,struck:state.complimentary});
      if(state.followups.two) rows.push({label:"Follow-up 2",amount:120,struck:state.complimentary});
      for(var n=0;n<rows.length;n++){
        var row = rows[n], rowY=209+n*40, value=money(row.amount);
        fitText(row.label,20,rowY,170,21,17,"bold");
        ctx.font="bold 21px Arial, sans-serif";
        ctx.textAlign="right";
        ctx.fillText(value,300,rowY);
        if(row.struck){
          var metrics=ctx.measureText(value);
          var strikeY=Math.round(rowY+(metrics.actualBoundingBoxDescent-metrics.actualBoundingBoxAscent)/2);
          ctx.fillRect(Math.round(300-metrics.width)-1,strikeY,Math.ceil(metrics.width)+2,2);
        }
      }
      ctx.fillRect(20,391,280,2);
      fitText("TOTAL",20,411,115,21,21,"bold");
      var total = money(grandTotal());
      ctx.textAlign="right";
      ctx.font="bold 30px Arial, sans-serif";
      if(ctx.measureText(total).width>160) ctx.font="bold 26px Arial, sans-serif";
      ctx.fillText(total,300,404);

      // Quantize before both preview and printing; they share these pixels.
      var pixels = ctx.getImageData(0,0,320,480);
      for(var i=0;i<pixels.data.length;i+=4){
        var v=pixels.data[i]<160 ? 0 : 255;
        pixels.data[i]=pixels.data[i+1]=pixels.data[i+2]=v;
        pixels.data[i+3]=255;
      }
      ctx.putImageData(pixels,0,0);
      var preview=canvas.toDataURL("image/png");
      var commands=["SIZE 40 mm,60 mm","GAP 2 mm,0 mm","DIRECTION 1","REFERENCE 0,0","CLS"];
      [[0,190],[190,390],[390,480]].forEach(function(band){
        var minX=320,maxX=-1,minY=480,maxY=-1;
        for(var y=band[0];y<band[1];y++) for(var x=0;x<320;x++){
          if(pixels.data[(y*320+x)*4]===0){
            if(x<minX)minX=x;if(x>maxX)maxX=x;
            if(y<minY)minY=y;if(y>maxY)maxY=y;
          }
        }
        if(maxX<0) return;
        var left=Math.floor(minX/8)*8,bytesWide=Math.ceil((maxX+1-left)/8);
        var data="";
        for(var yy=minY;yy<=maxY;yy++) for(var bx=0;bx<bytesWide;bx++){
          var bits=0;
          for(var bit=0;bit<8;bit++){
            var xx=left+bx*8+bit;
            if(xx<320 && pixels.data[(yy*320+xx)*4]===0)bits|=128>>bit;
          }
          data+=String.fromCharCode(255-bits);
        }
        commands.push("BITMAP "+left+","+minY+","+bytesWide+","+(maxY-minY+1)+",0,"+data);
      });
      commands.push("PRINT 1,1","");
      quotationArtworkCache={key:key,preview:preview,tspl:commands.join("\r\n")};
      return quotationArtworkCache;
    }
