    var EXTENSION_BITMAPS = {
      stellest: [BOOKLET_BITMAPS.stellest[0],BOOKLET_BITMAPS.stellest[1],BIOMETRY_EXTENSION_BLOCK_BITMAP,BOOKLET_BITMAPS.stellest[3],BOOKLET_BITMAPS.stellest[4]],
      stellest2: [BOOKLET_BITMAPS.stellest2[0],BOOKLET_BITMAPS.stellest2[1],BIOMETRY_EXTENSION_BLOCK_BITMAP,BOOKLET_BITMAPS.stellest2[3],BOOKLET_BITMAPS.stellest2[4]]
    };
    function rotatedBitmapCommands(segments){
      var commands = ["SIZE 40 mm,60 mm","GAP 2 mm,0 mm","DIRECTION 1","REFERENCE 0,0","CLS"];
      for(var i=0;i<segments.length;i++){
        var segment = segments[i];
        commands.push("BITMAP "+segment.x+","+segment.y+","+segment.w+","+segment.h+",0,"+hexToBinary(segment.hex,true));
      }
      commands.push("PRINT 1,1","");
      return commands.join("\r\n");
    }
    function buildLabelTSPL(kind){
      var key=currentProduct().key;
      if(kind==="warranty") return rotatedBitmapCommands(GUARANTEE_BITMAPS[key]);
      if(kind==="booklet") return rotatedBitmapCommands(BOOKLET_BITMAPS[key]);
      if(kind==="extension") return rotatedBitmapCommands(EXTENSION_BITMAPS[key]);
      if(kind==="quotation") return quotationArtwork().tspl;
      throw new Error("Unknown label type");
    }
    function sleep(ms){return new Promise(function(resolve){window.setTimeout(resolve,ms)})}
    async function printerChannels(){
      if(!navigator.bluetooth) throw new Error("Web Bluetooth is not available. Open the catalogue in Bluefy/WebBLE on iPad.");
      if(!labelPrinterDevice){
        labelPrinterDevice = await navigator.bluetooth.requestDevice({
          filters:[{namePrefix:"D520"},{namePrefix:"D520BT"},{namePrefix:"D520BT-Z"},{namePrefix:"D"}],
          optionalServices:[D520_SERVICE_UUID]
        });
      }
      var server = labelPrinterDevice.gatt.connected ? labelPrinterDevice.gatt : await labelPrinterDevice.gatt.connect();
      var service = await server.getPrimaryService(D520_SERVICE_UUID);
      var writeCharacteristic = await service.getCharacteristic(D520_WRITE_UUID);
      try{
        var notify = await service.getCharacteristic(D520_NOTIFY_UUID);
        await notify.startNotifications();
      }catch(ignore){}
      return writeCharacteristic;
    }
    async function writeChunks(characteristic,text,labelName){
      var bytes = new Uint8Array(text.length);
      for(var n=0;n<text.length;n++) bytes[n] = text.charCodeAt(n) & 255;
      for(var i=0;i<bytes.length;i+=20){
        var chunk = bytes.slice(i,i+20);
        if(characteristic.properties.writeWithoutResponse && characteristic.writeValueWithoutResponse) await characteristic.writeValueWithoutResponse(chunk);
        else await characteristic.writeValue(chunk);
        if(labelName && (i % 400 < 20 || i+20>=bytes.length))
          setPrintStatus("Sending " + labelName.toLowerCase() + "… " + Math.min(100,Math.round((i+chunk.length)*100/bytes.length)) + "%","busy");
        await sleep(35);
      }
    }
    async function printToD520(kind){
      var labelName = kind==="extension" ? "Biometry follow-up extension" : (kind==="booklet" ? "Booklet label" : (kind==="warranty" ? "Guarantee" : "Quotation"));
      setPrintButtonsDisabled(true);
      try{
        setPrintStatus("Connecting to D520BT-Z…","busy");
        var characteristic = await printerChannels();
        setPrintStatus("Sending " + labelName.toLowerCase() + "…","busy");
        await writeChunks(characteristic,buildLabelTSPL(kind),labelName);
        await sleep(1000);
        setPrintStatus(labelName + " sent to D520BT-Z","success");
      }catch(error){
        setPrintStatus("Print failed: " + (error&&error.message?error.message:String(error)),"error");
      }finally{
        if(labelPrinterDevice && labelPrinterDevice.gatt && labelPrinterDevice.gatt.connected) labelPrinterDevice.gatt.disconnect();
        setPrintButtonsDisabled(false);
      }
    }

